/**
 * The live dataset: multi-step integer arithmetic, generated by code from a
 * fixed seed. Every item has one exact integer answer, computed here, so the
 * scorer never needs a model to decide what is right.
 */
import { hashString } from "@/lib/data/derive";
import type { Dataset } from "@/lib/data/types";
import { mulberry32 } from "@/lib/stats";

export interface Item {
  id: string;
  /** What the target is asked. */
  prompt: string;
  /** The expression, for display. */
  expression: string;
  /** The exact answer. */
  answer: number;
}

export const DATASET = {
  id: "helper-arithmetic-v2",
  name: "helper-arithmetic-v2",
  seed: 20261009,
  description: "Seeded multi-step integer arithmetic (products of a 4-digit and a 3-digit number, combined with a third term); exact answers computed by code. Hard enough that working it through matters.",
} as const;

/** Most items any run can use (the per-arm ceiling). */
export const DATASET_MAX = 100;

function between(rand: () => number, lo: number, hi: number) {
  return lo + Math.floor(rand() * (hi - lo + 1));
}

/** The first `n` items for a seed. Same seed, same items, in the same order. */
export function makeItems(n: number, seed: number = DATASET.seed): Item[] {
  const rand = mulberry32(seed);
  const items: Item[] = [];
  for (let i = 0; i < n; i++) {
    const a = between(rand, 1001, 9999);
    const b = between(rand, 101, 999);
    const c = between(rand, 1001, 9999);
    const d = between(rand, 101, 999);
    const e = between(rand, 10001, 99999);
    const form = i % 3;
    let expression: string;
    let answer: number;
    if (form === 0) {
      expression = `(${a} * ${b}) - (${c} * ${d}) + ${e}`;
      answer = a * b - c * d + e;
    } else if (form === 1) {
      expression = `(${a} + ${c}) * ${b} - ${e}`;
      answer = (a + c) * b - e;
    } else {
      expression = `(${a} * ${b}) + (${c} * ${d}) - ${e}`;
      answer = a * b + c * d - e;
    }
    items.push({ id: `A${String(i + 1).padStart(3, "0")}`, prompt: `What is ${expression}?`, expression, answer });
  }
  return items;
}

/** A content hash of the items, recorded on every run. */
export function itemsHash(items: Item[]): string {
  return `fnv1a:${hashString(JSON.stringify(items.map((x) => [x.id, x.prompt, x.answer]))).toString(16).padStart(8, "0")}`;
}

/** The dataset as a catalog entry, so the workspace can describe live experiments. */
export function liveDataset(): Dataset {
  const sample = makeItems(5);
  return {
    id: DATASET.id,
    name: DATASET.name,
    size: DATASET_MAX,
    split: "custom",
    heldOut: null,
    // Each run records the hash of the items it used (they depend on n).
    hash: null,
    description: DATASET.description,
    schema: [
      { name: "id", type: "string", description: "Item id, A001 onwards" },
      { name: "prompt", type: "string", description: "The question the target is asked" },
      { name: "answer", type: "integer", description: "Exact answer, computed by code" },
    ],
    sampleRows: sample.map((x) => ({ id: x.id, prompt: x.prompt, answer: String(x.answer) })),
  };
}
